-- RedeVita - script completo para MySQL
-- Execute no MySQL Workbench / phpMyAdmin para criar as tabelas e carregar os medicamentos de referência.
-- Depois configure no .env: DATABASE_URL=mysql+pymysql://root:SUA_SENHA@localhost/redevita

CREATE DATABASE IF NOT EXISTS redevita CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE redevita;

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS usuarios (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(100) NOT NULL,
  cpf VARCHAR(14) NOT NULL UNIQUE,
  email VARCHAR(150) NULL UNIQUE,
  senha VARCHAR(255) NOT NULL,
  cargo VARCHAR(50) DEFAULT 'Voluntário',
  ativo BOOLEAN DEFAULT TRUE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS medicamentos_referencia (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nome_comercial VARCHAR(120) NOT NULL,
  registro_ms VARCHAR(30) NULL,
  principio_ativo VARCHAR(120) NULL,
  tarja VARCHAR(30) NOT NULL DEFAULT 'Sem Tarja',
  uso_continuo BOOLEAN DEFAULT FALSE,
  tipo_receita VARCHAR(60) NULL,
  lista_portaria VARCHAR(10) NULL,
  UNIQUE KEY uq_medicamentos_referencia_nome (nome_comercial)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS medicamentos (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(100) NOT NULL,
  lote VARCHAR(50) NOT NULL,
  data_validade DATE NOT NULL,
  quantidade INT DEFAULT 0,
  status_semaforo INT DEFAULT 0,
  tarja VARCHAR(30) NOT NULL DEFAULT 'Sem Tarja',
  principio_ativo VARCHAR(120) NULL,
  uso_continuo BOOLEAN DEFAULT FALSE,
  referencia_id INT NULL,
  CONSTRAINT fk_medicamentos_referencia FOREIGN KEY (referencia_id) REFERENCES medicamentos_referencia(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS medicos (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(150) NOT NULL,
  crm VARCHAR(30) NOT NULL UNIQUE,
  especialidade VARCHAR(100) NOT NULL,
  contato VARCHAR(30) NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS farmacias (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nome_fantasia VARCHAR(150) NOT NULL,
  razao_social VARCHAR(200) NULL,
  cnpj VARCHAR(20) NOT NULL UNIQUE,
  endereco VARCHAR(255) NOT NULL,
  responsavel VARCHAR(150) NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS pacientes (
  id INT AUTO_INCREMENT PRIMARY KEY,
  nome VARCHAR(150) NOT NULL,
  cpf VARCHAR(14) NOT NULL UNIQUE,
  data_nascimento DATE NOT NULL,
  endereco VARCHAR(255) NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS receitas (
  id INT AUTO_INCREMENT PRIMARY KEY,
  paciente_id INT NOT NULL,
  medico_id INT NOT NULL,
  medicamento_id INT NULL,
  observacoes TEXT NULL,
  data_emissao DATETIME DEFAULT CURRENT_TIMESTAMP,
  tipo_receita VARCHAR(60) NULL,
  imagem_url VARCHAR(255) NULL,
  status VARCHAR(20) NOT NULL DEFAULT 'pendente',
  dispensada_em DATETIME NULL,
  dispensada_por_id INT NULL,
  CONSTRAINT fk_receitas_paciente FOREIGN KEY (paciente_id) REFERENCES pacientes(id) ON DELETE CASCADE,
  CONSTRAINT fk_receitas_medico FOREIGN KEY (medico_id) REFERENCES medicos(id) ON DELETE RESTRICT,
  CONSTRAINT fk_receitas_medicamento FOREIGN KEY (medicamento_id) REFERENCES medicamentos(id) ON DELETE SET NULL,
  CONSTRAINT fk_receitas_usuario FOREIGN KEY (dispensada_por_id) REFERENCES usuarios(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS doacoes (
  id INT AUTO_INCREMENT PRIMARY KEY,
  usuario_id INT NOT NULL,
  medicamento_id INT NOT NULL,
  data_doacao DATETIME DEFAULT CURRENT_TIMESTAMP,
  quantidade INT NOT NULL,
  CONSTRAINT fk_doacoes_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE,
  CONSTRAINT fk_doacoes_medicamento FOREIGN KEY (medicamento_id) REFERENCES medicamentos(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS logs_atividade (
  id INT AUTO_INCREMENT PRIMARY KEY,
  usuario_id INT NULL,
  acao VARCHAR(100) NOT NULL,
  detalhes VARCHAR(500) NULL,
  ip VARCHAR(45) NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT fk_logs_usuario FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;

-- Usuários de apresentação. Senha de todos: admin123
ON DUPLICATE KEY UPDATE
  nome = VALUES(nome),
  email = VALUES(email),
  senha = VALUES(senha),
  cargo = VALUES(cargo),
  ativo = VALUES(ativo);

-- Medicamentos de referência ANVISA/Portaria 344 usados pelo sistema (386 registros).
ON DUPLICATE KEY UPDATE
  registro_ms = VALUES(registro_ms),
  principio_ativo = VALUES(principio_ativo),
  tarja = VALUES(tarja),
  uso_continuo = VALUES(uso_continuo),
  tipo_receita = VALUES(tipo_receita),
  lista_portaria = VALUES(lista_portaria);

ON DUPLICATE KEY UPDATE
  registro_ms = VALUES(registro_ms),
  principio_ativo = VALUES(principio_ativo),
  tarja = VALUES(tarja),
  uso_continuo = VALUES(uso_continuo),
  tipo_receita = VALUES(tipo_receita),
  lista_portaria = VALUES(lista_portaria);

ON DUPLICATE KEY UPDATE
  registro_ms = VALUES(registro_ms),
  principio_ativo = VALUES(principio_ativo),
  tarja = VALUES(tarja),
  uso_continuo = VALUES(uso_continuo),
  tipo_receita = VALUES(tipo_receita),
  lista_portaria = VALUES(lista_portaria);

ON DUPLICATE KEY UPDATE
  registro_ms = VALUES(registro_ms),
  principio_ativo = VALUES(principio_ativo),
  tarja = VALUES(tarja),
  uso_continuo = VALUES(uso_continuo),
  tipo_receita = VALUES(tipo_receita),
  lista_portaria = VALUES(lista_portaria);

ON DUPLICATE KEY UPDATE
  registro_ms = VALUES(registro_ms),
  principio_ativo = VALUES(principio_ativo),
  tarja = VALUES(tarja),
  uso_continuo = VALUES(uso_continuo),
  tipo_receita = VALUES(tipo_receita),
  lista_portaria = VALUES(lista_portaria);

SELECT 'Banco RedeVita pronto para uso no MySQL.' AS status;